import{_ as r,o as a,c as t,ah as i}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Guide — Direction","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/direction.md","filePath":"src/guide/direction.md"}'),n={name:"guide/direction.md"};function o(s,e,u,l,d,c){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="guide-—-direction" tabindex="-1">Guide — Direction <a class="header-anchor" href="#guide-—-direction" aria-label="Permalink to &quot;Guide — Direction&quot;">​</a></h1><p>Vue consolidée de l&#39;activité, tous portefeuilles confondus.</p><h2 id="bienvenue-sur-naia" tabindex="-1">Bienvenue sur Naia <a class="header-anchor" href="#bienvenue-sur-naia" aria-label="Permalink to &quot;Bienvenue sur Naia&quot;">​</a></h2><p>Votre espace Naia vous donne une vue consolidée de l&#39;ensemble des projets et indicateurs financiers d&#39;edPage group. Vous la consultez en lecture seule, à une exception près : la décision de bloquer un projet pour impayé.</p><h2 id="vue-consolidee-des-projets" tabindex="-1">Vue consolidée des projets <a class="header-anchor" href="#vue-consolidee-des-projets" aria-label="Permalink to &quot;Vue consolidée des projets&quot;">​</a></h2><ul><li>Accédez à une vue de l&#39;ensemble des projets en cours, tous chefs de projet et portefeuilles confondus.</li><li>Identifiez en un coup d&#39;œil les <strong>projets à risque</strong> sans ouvrir chaque fiche projet : ceux dont le pôle Facturation a signalé un retard de paiement en attente de votre décision (en tête de liste), et ceux déjà bloqués pour impayé, avec leur date de blocage.</li></ul><h2 id="indicateurs-financiers" tabindex="-1">Indicateurs financiers <a class="header-anchor" href="#indicateurs-financiers" aria-label="Permalink to &quot;Indicateurs financiers&quot;">​</a></h2><ul><li>Consultez les indicateurs financiers globaux : chiffre d&#39;affaires facturé et encaissé, factures en attente ou en retard, commissions dues et versées aux apporteurs d&#39;affaires.</li><li>Suivez la performance de chaque apporteur d&#39;affaires (nombre de clients apportés, chiffre d&#39;affaires généré, commissions dues et versées).</li></ul><h2 id="decider-du-blocage-pour-impaye" tabindex="-1">Décider du blocage pour impayé <a class="header-anchor" href="#decider-du-blocage-pour-impaye" aria-label="Permalink to &quot;Décider du blocage pour impayé&quot;">​</a></h2><p>Quand le pôle Facturation signale un paiement <strong>en retard</strong> sur un jalon facturable, vous êtes alerté dans l&#39;application et par e-mail. Rien n&#39;est bloqué automatiquement : c&#39;est à vous — ou à l&#39;administrateur — de décider, depuis la fiche du projet.</p><ul><li><strong>Bloquer le projet</strong> : les tâches déjà démarrées peuvent se terminer, mais personne ne peut démarrer de nouvelle tâche ni valider de jalon. Le client peut toujours consulter, échanger et surtout payer. Le chef de projet et l&#39;équipe sont notifiés.</li><li><strong>Ne pas bloquer</strong> : le projet continue normalement ; le signalement est considéré comme traité.</li><li>Quand le pôle Facturation signale le retour <strong>à jour</strong>, <strong>débloquez le projet</strong> depuis sa fiche.</li></ul><p>Seul le projet concerné est bloqué, jamais les autres projets du même client. Une facture interne en retard ne déclenche pas d&#39;alerte à votre intention : seul le signalement du pôle Facturation compte.</p><h2 id="perimetre-de-votre-acces" tabindex="-1">Périmètre de votre accès <a class="header-anchor" href="#perimetre-de-votre-acces" aria-label="Permalink to &quot;Périmètre de votre accès&quot;">​</a></h2><p>En dehors du blocage pour impayé, votre accès est limité à la consultation : vous n&#39;avez accès ni à la gestion des comptes et des rôles, ni aux paramètres de sécurité, ni à la messagerie des projets — ces aspects restent réservés à l&#39;Administrateur et au Chef de projet.</p>',14)])])}const f=r(n,[["render",o]]);export{m as __pageData,f as default};
